9	// ── Security: CORS — restrict to localhost origins ────────────────────────────
10	const ALLOWED_ORIGINS = new Set([
11	  'http://localhost:3847',
12	  'http://localhost:5173',   // Vite dev
13	  'http://localhost:3000',
14	  'http://localhost:8080',
15	  'http://127.0.0.1:3847',
16	  'http://127.0.0.1:5173',
17	  'http://127.0.0.1:3000',
18	  'http://127.0.0.1:8080',
19	]);
